import { defineConfig } from 'vite';
import { resolve } from 'node:path';
import { fileURLToPath } from 'node:url';
import { existsSync, readFileSync } from 'node:fs';

const rootDir = fileURLToPath(new URL('.', import.meta.url));
// L393: auto-generated by the npm predev/prebuild lifecycle. Map all real
// Babylon deep subpath imports to small ES re-export shims backed by ONE
// genuine esbuild vendor. No absolute machine paths, CDN or replaced classes.
const aliasesFile = resolve(rootDir, '.l393-generated', 'l393_aliases.json');
const regexCharacters = new Set([
  '.', '*', '+', '?', '^', '$', '{', '}', '(', ')', '|', '[', ']',
  String.fromCharCode(92),
]);
const exactImportMatcher = specifier => new RegExp('^' + [...specifier]
  .map(character => regexCharacters.has(character)
    ? String.fromCharCode(92) + character : character).join('') + '$');
function nativeVendorAliases() {
  if (!existsSync(aliasesFile)) {
    throw new Error('L393 vendor missing: run npm run build or npm run dev (not vite directly)');
  }
  const aliasSpec = JSON.parse(readFileSync(aliasesFile, 'utf8'));
  return Object.entries(aliasSpec).map(([specifier, entry]) => ({
    // EXACT match. Vite bare string aliases match subpath prefixes and would
    // accidentally append e.g. /Cameras/arcRotateCamera.js to shim_00.mjs.
    find: exactImportMatcher(specifier),
    replacement: resolve(rootDir, entry.relative_shim),
  }));
}
const startedAt = Date.now();
let modulesParsed = 0;
let buildAliasCount = 0;
const buildTelemetry = {
  name: 'l393-portable-genuine-babylon-vendor',
  buildStart() {
    console.log('[L393_BUILD] authentic exact deep aliases=' + buildAliasCount);
  },
  moduleParsed(info) {
    modulesParsed++;
    if (modulesParsed === 1 || modulesParsed % 40 === 0) {
      console.log('[L393_BUILD] parsed=' + modulesParsed +
        ' elapsed_s=' + ((Date.now() - startedAt) / 1000).toFixed(1) +
        ' RSS_MB=' + Math.round(process.memoryUsage().rss / 1048576));
    }
  },
  closeBundle() {
    console.log('[L393_BUILD] PASS closed; parsed=' + modulesParsed +
      ' elapsed_s=' + ((Date.now() - startedAt) / 1000).toFixed(1));
  },
};

export default defineConfig(({ mode }) => {
  // Unit tests must use the REAL installed Babylon package, not the smaller
  // 49-symbol production vendor. Vitest needs NullEngine and test-only APIs
  // not imported by the UI, and should run without generated build assets.
  const isVitest = mode === 'test' || Boolean(process.env.VITEST)
    || process.env.NODE_ENV === 'test'
    || process.argv.some(arg => /vitest/i.test(arg));
  const aliases = isVitest ? [] : nativeVendorAliases();
  buildAliasCount = aliases.length;
  return {
  resolve: { alias: aliases },
  plugins: isVitest ? [] : [buildTelemetry],
  server: {
    // Chrome's local QA profile contains locked SQLite databases that cannot
    // be watched by Vite on Windows; it is not part of the application.
    watch: { ignored: ['**/qa-artifacts/pipe-cdp-profile/**'] },
  },
  build: {
    target: 'es2022',
    minify: false,
    sourcemap: false,
    cssCodeSplit: true,
    reportCompressedSize: false,
    rollupOptions: {
      treeshake: false,
      input: {
        main: resolve(rootDir, 'index.html'),
        babylonPreview: resolve(rootDir, 'babylon-preview.html'),
      },
    },
  },
  };
});
